gTz(){return"\u0644\u0627\u0628\u0631\u062f\u0646\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0628\u06d5\u0647\u0627\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u0695\u0627\u067e\u06c6\u0631\u062a\u06d5"},
gag_(){return"\u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0628\u06cc\u062e\u0648\u06ce\u0646\u06d5\u0631\u06d5\u0648\u06d5"},
gafp(){return"\u067e\u0634\u06a9\u0646\u06cc\u0646"},
gTy(){return"\u0628\u06d5\u0647\u0627"},
