gafL(){return"\u0628\u06d5 \u0646\u0627\u0648 \u06cc\u0627\u0646 \u06a9\u06c6\u062f \u0628\u06af\u06d5\u0695\u06ce"},
gafK(){return"\u0647\u06cc\u0686 \u067e\u0634\u06a9\u0646\u06cc\u0646\u06ce\u06a9 \u0646\u0627\u06af\u0648\u0646\u062c\u06ce\u062a"},
