gao3(){return"\u067e\u06d5\u0695\u06d5\u06a9\u06d5 \u0648\u06d5\u06a9 \u0648\u06ce\u0646\u06d5\u06cc \u0644\u06ce\u06af\u06cc\u0631\u0627\u0648\u06d5"},
gaoN(){return"\u0647\u06cc\u0686 \u0646\u0627\u0633\u06ce\u0646\u06d5\u0631\u06ce\u06a9\u062a \u067e\u06ce\u0646\u0627\u06af\u0627\u062a: \u0646\u06d5 \u0646\u0627\u0648\u060c \u0646\u06d5 \u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc\u060c \u0646\u06d5 \u062a\u06d5\u0645\u06d5\u0646\u060c \u0646\u06d5 \u0695\u06d5\u06af\u06d5\u0632\u060c \u0648 \u0646\u06d5 \u06cc\u06d5\u06a9 \u062f\u06ce\u0695\u06cc \u062a\u0631\u06cc \u062a\u06c6\u0645\u0627\u0631\u06cc \u0626\u06d5\u0645 \u0646\u06d5\u062e\u06c6\u0634\u06d5."},
